n, m = map(int, raw_input().split())

if m > n:
    m, n = n, m

if m >= 3:
    result = m * n
    if result % 2:
        result -= 1
    print result
elif m == 2:
    if n == 2:
        print 0
    elif n == 3:
        print 4
    elif n == 7:
        print 12
    else:
        print n * m
else:
    remainder = n % 6
    quotient = n / 6
    if remainder == 5:
        quotient += 4
    elif remainder == 4:
        quotient += 2
    print quotient * 6

