from sys import stdin, stdout

n, m = map(int, stdin.readline().split())

if m > n:
    n, m = n, m

if m >= 3:
    result = m * n
    if result % 2:
        result -= 1
    stdout.write(str(result) + "\n")
elif m == 2:
    if n == 2:
        stdout.write("0\n")
    elif n == 3:
        stdout.write("4\n")
    elif n == 7:
        stdout.write("12\n")
    else:
        stdout.write(str(n * m) + "\n")
else:
    remainder = n % 6
    quotient = n / 6
    if remainder == 5:
        quotient += 4
    elif remainder == 4:
        quotient += 2
    stdout.write(str(quotient * 6) + "\n")

